const r = await tools.exec_command({cmd:"python - <<'PY'
import json, numpy as np
from scipy.linalg import eigh
from model import response
n=6;dim=1<<n
cs=[]
for a in range(n):
 x=np.zeros((dim,dim),complex)
 for state in range(dim):
  if state>>a&1:
   x[state^(1<<a),state]=(-1)**((state & ((1<<a)-1)).bit_count())
 cs.append(x)
cd=[x.conj().T for x in cs]
def direct(e):
 hs=np.diag(np.array([-.35,.15,.7])+e['offset'])
 for i,j,w in [(0,1,1.),(1,2,.8),(0,2,.3)]:hs[i,j]=hs[j,i]=-e['hopping']*w
 h=np.kron(hs,np.eye(2));H=np.zeros((dim,dim),complex)
 for i in range(n):
  for j in range(n): H += h[i,j]*cd[i]@cs[j]
 for i,(d,b) in enumerate(zip([1.,.85,1.15],[0.,1.,-.4])):
  z=e['pairing']*d*np.exp(1j*e['phase']*b);u,dn=2*i,2*i+1
  H += z*cd[u]@cd[dn] + z.conjugate()*cs[dn]@cs[u]
 S=.5*(cd[2*e['site']]@cs[2*e['site']]-cd[2*e['site']+1]@cs[2*e['site']+1])
 E,V=eigh(H); p=np.exp(-(E-E.min())/e['temperature']);p/=p.sum();M=V.conj().T@S@V
 fr=E[:,None]-E[None,:];band=np.where(fr>0,fr**2*np.exp(-.5*((fr-e['center'])/e['width'])**2),0)
 return np.sum(p[None,:]*abs(M)**2*band)
# create pairing random based calibration first record
for e in [dict(hopping=.7,pairing=.8,temperature=.4,site=1,center=1.8,width=.5,phase=.9,offset=.1), dict(hopping=.55,pairing=.2,temperature=.3,site=0,center=2.5,width=.7,phase=-1.2,offset=-.2)]:
 print('e',e,'current',response(e),'direct',direct(e),'ratio',direct(e)/response(e))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000});
text(r.output);

